-- 0038_catalog_complete.sql
-- Panini FIFA World Cup 2026 (Ecuador Edition): WIPE v1 + complete real catalog
-- 1013 cromos: 48 selecciones x 20 + 9 FWC + 11 MUSEUM + 13 COCA (Coca-Cola Ecuador) + 20 EXTRA International
-- Sources: paniniwm2026sticker.com, checklistinsider.com, diamondcardsonline.com, primicias.ec, masmildeaura.com
BEGIN;

-- 1) Wipe v1 catalog (synthetic) and dependent FKs.
DELETE FROM public.transaction_items WHERE cromo_id IN (SELECT id FROM public.catalog_cromos WHERE catalog_version = 1);
DELETE FROM public.listing_items WHERE cromo_id IN (SELECT id FROM public.catalog_cromos WHERE catalog_version = 1);
DELETE FROM public.inventory_items WHERE cromo_id IN (SELECT id FROM public.catalog_cromos WHERE catalog_version = 1);
DELETE FROM public.catalog_cromos WHERE catalog_version = 1;

-- 1b) Drop old COCA (12 USA-edition rows) before re-seeding 13 Ecuador-edition.
DELETE FROM public.transaction_items WHERE cromo_id IN (SELECT id FROM public.catalog_cromos WHERE section_code = 'COCA' AND catalog_version = 2);
DELETE FROM public.listing_items WHERE cromo_id IN (SELECT id FROM public.catalog_cromos WHERE section_code = 'COCA' AND catalog_version = 2);
DELETE FROM public.inventory_items WHERE cromo_id IN (SELECT id FROM public.catalog_cromos WHERE section_code = 'COCA' AND catalog_version = 2);
DELETE FROM public.catalog_cromos WHERE section_code = 'COCA' AND catalog_version = 2;

-- 2) Upsert 48 countries (stripe2 = accent for legacy column).

-- 3) Upsert all 1013 cromos as catalog_version = 2, is_active = true.
-- printed_code is a generated column (omitted).

COMMIT;
